legacy_active_turn.sql:
WITH snapshots(doc) AS (
 SELECT snapshot_json FROM conversation_machine_snapshots
) SELECT count(*) FROM snapshots WHERE json_type(doc,'$.context.activeTurn')='object' AND json_type(doc,'$.context.activeTurn.kind') IS NULL

legacy_debug_generation.sql:
WITH snapshots(doc) AS (
 SELECT snapshot_json FROM conversation_machine_snapshots
) SELECT count(*) FROM snapshots WHERE json_type(doc,'$.context.debugMode.active')='true' AND (coalesce(json_type(doc,'$.context.debugMode.debugSessionId'),'missing') != 'text' OR json_extract(doc,'$.context.debugMode.debugSessionId')='')
